376	// A small JSON Schema validator for the subset scripts/gen_protocol_schema.mjs emits (draft 2020-12 keywords: type,
377	// const, enum, properties, required, additionalProperties, items, prefixItems, minItems, maxItems, anyOf, oneOf and a
378	// local $ref). It is a test helper, not a general validator: a keyword outside that subset throws, so a generator that
379	// starts emitting a new keyword cannot pass unvalidated.
380	import { isDeepStrictEqual } from "node:util";
381	
382	export type Schema = Record<string, any>;
383	
384	const ANNOTATIONS = new Set(["$schema", "$defs", "title", "description"]);
385	const KEYWORDS = new Set(["$ref", "type", "const", "enum", "properties", "required", "additionalProperties", "items", "prefixItems", "minItems", "maxItems", "anyOf", "oneOf"]);
386	
387	function typeName(value: unknown): string {
388	  if (value === null) return "null";
389	  if (Array.isArray(value)) return "array";
390	  return typeof value;
391	}
392	
393	function resolve(root: Schema, ref: string): Schema {
394	  if (!ref.startsWith("#/")) throw new Error(`unsupported $ref: ${ref}`);
395	  let node: any = root;
396	  for (const part of ref.slice(2).split("/")) node = node?.[part.replace(/~1/g, "/").replace(/~0/g, "~")];
397	  if (!node || typeof node !== "object") throw new Error(`unresolved $ref: ${ref}`);
398	  return node;
399	}
400	
401	/** Every way `value` fails `schema`, as `path: reason` lines; empty when it is valid. `root` resolves `$ref`. */
402	export function validate(value: unknown, schema: Schema, root: Schema = schema, at = "$"): string[] {
403	  for (const keyword of Object.keys(schema)) {
404	    if (!KEYWORDS.has(keyword) && !ANNOTATIONS.has(keyword)) throw new Error(`unsupported schema keyword at ${at}: ${keyword}`);
405	  }
406	  const errors: string[] = [];
407	  if (schema.$ref) errors.push(...validate(value, resolve(root, schema.$ref), root, at));
408	  const actual = typeName(value);
409	  if (schema.type !== undefined && actual !== schema.type) errors.push(`${at}: expected ${schema.type}, got ${actual}`);
410	  if ("const" in schema && !isDeepStrictEqual(value, schema.const)) errors.push(`${at}: expected ${JSON.stringify(schema.const)}`);
411	  if (schema.enum && !schema.enum.some((allowed: unknown) => isDeepStrictEqual(value, allowed))) errors.push(`${at}: not one of ${JSON.stringify(schema.enum)}`);
412	
413	  if (actual === "object") {
414	    const object = value as Record<string, unknown>;
415	    const properties: Record<string, Schema> = schema.properties ?? {};
416	    for (const name of schema.required ?? []) {
417	      if (!Object.hasOwn(object, name)) errors.push(`${at}: missing required ${name}`);
418	    }
419	    for (const [name, member] of Object.entries(object)) {
420	      if (Object.hasOwn(properties, name)) errors.push(...validate(member, properties[name], root, `${at}.${name}`));
421	      else if (schema.additionalProperties === false) errors.push(`${at}: unexpected property ${name}`);
422	      else if (typeof schema.additionalProperties === "object") errors.push(...validate(member, schema.additionalProperties, root, `${at}.${name}`));
423	    }
424	  }
425	
426	  if (actual === "array") {
427	    const array = value as unknown[];
428	    const prefix: Schema[] = schema.prefixItems ?? [];
429	    if (schema.minItems !== undefined && array.length < schema.minItems) errors.push(`${at}: fewer than ${schema.minItems} items`);
430	    if (schema.maxItems !== undefined && array.length > schema.maxItems) errors.push(`${at}: more than ${schema.maxItems} items`);
431	    array.forEach((item, i) => {
432	      if (i < prefix.length) errors.push(...validate(item, prefix[i], root, `${at}[${i}]`));
433	      else if (schema.items) errors.push(...validate(item, schema.items, root, `${at}[${i}]`));
434	    });
435	  }
436	
437	  for (const keyword of ["anyOf", "oneOf"] as const) {
438	    if (!schema[keyword]) continue;
439	    const results: string[][] = schema[keyword].map((option: Schema) => validate(value, option, root, at));
440	    const matches = results.filter((result) => result.length === 0).length;
441	    if (matches === 1 || (matches > 1 && keyword === "anyOf")) continue;
442	    if (matches > 1) {
443	      errors.push(`${at}: matches ${matches} oneOf alternatives`);
444	      continue;
445	    }
446	    // Explain with the alternative that came closest. For a message union that is the variant whose `type` matched;
447	    // when no variant's did, the type is unknown and there is nothing more to say.
448	    const candidates = results.filter((result) => !result.some((error) => error.startsWith(`${at}.type:`)));
449	    const closest = candidates.reduce<string[]>((best, result) => (best.length === 0 || result.length < best.length ? result : best), []);
450	    errors.push(`${at}: matches no ${keyword} alternative`, ...closest);
451	  }
452	  return errors;
453	}
