    assert.equal(looserThan(merge3(), merge3(documentWith(row, strict))).length > 0, true, `${row.table}.${row.key} absent`);
    assert.deepEqual(looserThan(merge3(documentWith(row, strict)), merge3(documentWith(row, loose))), []);
  }
});

